      "narration": "Five days in Kyoto, 3–7 Nov 2026, and Sam is the whole crew.",
      "headline": "Kyoto"
    },
    "critters": {
      "narration": "Sam found 4 forms, and all 4 were new little locals worth a second look."
    },
    "route": {
      "narration": "From Gion to Fushimi Inari, over to Arashiyama, and on to Kinkaku-ji, about 41.2 kilometres of wandering.",
      "line": "The longest leg, Fushimi Inari to Arashiyama, ran 17.8 kilometres in 25 minutes, no driver required."
    },
    "awards": {
      "narration": "And now the awards, because one traveller still gets a shiny little nod."
    },
    "receipt": {
      "narration": "JPY 148,000 all in, which lands JPY 12,000 under the JPY 160,000 plan.",
      "line": "Settled, smiling, and the cheapest day was day 3 at JPY 4,800."
    },
    "stamp": {
      "narration": "A Kyoto stamp for the pass, 3–7 Nov 2026, signed with a happy little tail flick."
    },
    "postcard": {
      "narration": "One last card from Kyoto, sent home with a bow.",
      "line": "Wish you were here, but also glad it is just me and the moss."
    }
  },
